function star(x: number, y: number, size: number, n = 5): string {
  const points = Array.from({ length: n * 2 }, (_, i) => {
    const a = i * Math.PI / n - Math.PI / 2;
    const rad = i % 2 ? size * .45 : size;
    return `${(x + Math.cos(a) * rad).toFixed(2)},${(y + Math.sin(a) * rad).toFixed(2)}`;
  }).join(' ');
  return `<polygon points="${points}"/>`;
}
