const renderers: Record<string, (index: number) => string> = { animals: animal, dinosaurs: dinosaur, transport, underwater, fairytale, robots: robot, princess, alien, christmas };
const esc = (value: string) => value.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;' }[char]!));
/** Returns an original, standalone SVG. Unknown IDs throw instead of silently using unrelated art. */
export function getDrawingSvg(id: string): string {
  const drawing = drawings.find(item => item.id === id);
  if (!drawing) throw new Error(`Unknown drawing: ${id}`);
  const index = titles[drawing.packId].indexOf(drawing.title);
  const aquatic = drawing.packId === 'underwater' || (drawing.packId === 'transport' && [5, 6, 12].includes(index));
  const space = drawing.packId === 'alien' || (drawing.packId === 'transport' && index === 7);
  const winter = drawing.packId === 'christmas';
  let scenery = sceneGround(index, aquatic);
  if (space) scenery = star(108,139,24)+star(677,177,30)+star(704,563,19)+c(113,541,14)+line('M65 688 Q225 628 400 681 T735 684');
  else if (winter) scenery += snowflake(113,151,.8)+snowflake(689,191,.65)+snowflake(696,496,.5);
  else if (aquatic) scenery += bubble(109,171,1.3)+bubble(674,259,.9)+bubble(135,240,.6);
  else scenery += index % 3 === 0 ? sun(110,137,.8)+cloud(672,176,.65) : cloud(113,157,.7)+cloud(684,133,.6);
  if (drawing.packId === 'animals') {
    if (index === 1) scenery += g(c(0,0,42)+line('M-36 -19 Q0 0 -12 40 M1 -42 Q4 -7 39 14'),679,607,.7);
    if (index === 2) scenery += g(p('M-18 0 L18 0 L0 81Z')+leaf(0,0,-25)+leaf(0,0,25),663,555,.65,25);
    if (index === 6) scenery += g(r(-28,0,56,61,14)+r(-30,-7,60,16,6)+p('M-14 21 L13 21 L23 38 L12 53 L-13 53 L-23 38Z'),679,589,.8);
    if ([11,14].includes(index)) scenery += flower(112,575,.9)+flower(687,590,.9);
    if (index === 12) scenery += g(mushroom(),33,509,.33);
  }
  if (drawing.packId === 'dinosaurs') scenery += leaf(104,616,-25)+leaf(693,621,25);
  const body = renderers[drawing.packId](index);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="800" height="800" viewBox="0 0 800 800" role="img" aria-labelledby="drawing-title"><title id="drawing-title">${esc(drawing.title)}</title><rect width="800" height="800" fill="#ffffff"/><g fill="#ffffff" stroke="#26313d" stroke-width="6" stroke-linecap="round" stroke-linejoin="round">${scenery}<g transform="translate(150 130) scale(1.25)">${body}</g></g></svg>`;
}
